CREATE TABLE IF NOT EXISTS accommodation (id serial PRIMARY KEY, name text NOT NULL, slug text NOT NULL UNIQUE, "sourceUrl" text NOT NULL, "sourceDomain" text, location text, island text NOT NULL DEFAULT 'São Miguel', summary text, capacity integer, bedrooms integer, bathrooms text, "bedConfiguration" text, "propertyType" text, amenities jsonb NOT NULL DEFAULT '{}'::jsonb, rating text, "reviewCount" integer, "reviewHighlights" text, "reviewConcerns" text, "agentMaxSummary" text, "unresolvedQuestions" text, status text NOT NULL DEFAULT 'submitted', "researchStatus" text NOT NULL DEFAULT 'research-needed', "submittedByUserId" text NOT NULL, "submittedByName" text NOT NULL, "lastResearchedAt" timestamp, "publishedAt" timestamp, "archivedAt" timestamp, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS accommodation_availability (id serial PRIMARY KEY, "accommodationId" integer NOT NULL REFERENCES accommodation(id) ON DELETE CASCADE, "startDate" timestamp, "endDate" timestamp, nights integer, availability text NOT NULL DEFAULT 'unknown', currency text, "nightlyRate" text, fees text, taxes text, "totalPrice" text, "cancellationPolicy" text, "sourceUrl" text, "verificationMethod" text NOT NULL DEFAULT 'listing', confidence text NOT NULL DEFAULT 'unconfirmed', notes text, "checkedByUserId" text NOT NULL, "checkedByName" text NOT NULL, "checkedAt" timestamp NOT NULL DEFAULT now(), "createdAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS accommodation_research_note (id serial PRIMARY KEY, "accommodationId" integer NOT NULL REFERENCES accommodation(id) ON DELETE CASCADE, kind text NOT NULL DEFAULT 'finding', title text, body text NOT NULL, "sourceUrl" text, "createdByUserId" text NOT NULL, "createdByName" text NOT NULL, "isAgentMax" boolean NOT NULL DEFAULT false, "createdAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS accommodation_revision (id serial PRIMARY KEY, "accommodationId" integer NOT NULL REFERENCES accommodation(id) ON DELETE CASCADE, action text NOT NULL, "beforeData" jsonb, "afterData" jsonb, "actorUserId" text NOT NULL, "actorName" text NOT NULL, "createdAt" timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS accommodation_status_idx ON accommodation(status);
CREATE INDEX IF NOT EXISTS accommodation_research_status_idx ON accommodation("researchStatus");
CREATE INDEX IF NOT EXISTS accommodation_source_url_idx ON accommodation("sourceUrl");
CREATE INDEX IF NOT EXISTS accommodation_availability_lookup_idx ON accommodation_availability("accommodationId", "checkedAt");
CREATE INDEX IF NOT EXISTS accommodation_notes_lookup_idx ON accommodation_research_note("accommodationId", "createdAt");
CREATE INDEX IF NOT EXISTS accommodation_revisions_lookup_idx ON accommodation_revision("accommodationId", "createdAt");
